/*
 * ast/test/test_ast_data.c - the AST module data blocks (source-gmxj)
 *
 * Generated by: Claude Opus 5.5
 *
 * ast/ast_data.c is #included, so the objects under test are the real
 * blocks:
 *
 *   AST_$DATA  map "D E1DC80 AST_ size = 498" (A5 of every AST_ routine)
 *   AST_$AOT   map "D00 EC5400 AST_AOT ... size = F960": AST (the ASTE
 *              table, 0xEC5400) and AOT (the AOTE table, 0xEC7B60)
 *
 * Checked: the image addresses; the map symbols inside the blocks at their
 * A5 / segment offsets (target sizes: aste_t and aote_t are 0x14 / 0xC0
 * bytes only with 4-byte pointers, so those offsets are recomputed from the
 * target strides, and the absolute field offsets are compile-time asserts
 * on the target); the offsets that hold on every build (AOTH at the block
 * base, vol_indices[1] right after dism_ec, its bias slot overlaying
 * dism_ec's tail); the ASTE bias (AST_ASTE_ENTRY(seg) = aste[seg - 1], the
 * image's 0xEC5400 + (seg - 1)*0x14); the image's initial contents (the
 * table cells, the self-linked eventcounts, grow_ahead 8, update_timestamp
 * 0xFFFF, the timestamp mask 0x0278301C, the rest zero); and, through the
 * real AST_$GET_DISM_SEQN, that the code reads the block field.
 */

#include <stdint.h>
#include <stdio.h>
#include <stddef.h>
#include <string.h>

/* Avoid the macOS uid_t conflict - must come AFTER the system includes. */
#define uid_t ast_uid_t

/* ==========================================================================
 * Test framework
 * ========================================================================== */

static int tests_failed = 0;
static int tests_run = 0;

#define TEST(name) static void test_##name(void)
#define RUN_TEST(name)                                                        \
    do {                                                                      \
        printf("  Running %s... ", #name);                                    \
        tests_run++;                                                          \
        test_##name();                                                        \
        printf("done\n");                                                     \
    } while (0)

#define ASSERT_EQ(expected, actual)                                           \
    do {                                                                      \
        long long _e = (long long)(expected);                                 \
        long long _a = (long long)(actual);                                   \
        if (_e != _a) {                                                       \
            printf("FAILED\n    Expected: 0x%llx, Got: 0x%llx at line %d\n",  \
                   (unsigned long long)_e, (unsigned long long)_a, __LINE__); \
            tests_failed++;                                                   \
            return;                                                           \
        }                                                                     \
    } while (0)

#include "ast/ast_internal.h"

#include "../ast_data.c"
#include "../get_dism_seqn.c"

/* PTR_AST_$SET_TROUBLE_00e07272 is a DXM callback cell (host registry). */
#include "dxm/test/dxm_host_callbacks.h"
void AST_$SET_TROUBLE(uid_t **uid_ptr) { (void)uid_ptr; }

#define OFF(block, field) \
    ((long long)((const uint8_t *)&(block).field - (const uint8_t *)&(block)))

/* Target strides (asserted against sizeof on the target in ast/ast.h). */
#define TARGET_ASTE_SIZE 0x14
#define TARGET_AOTE_SIZE 0xC0

/* ==========================================================================
 * Tests
 * ========================================================================== */

TEST(block_addresses_and_sizes)
{
    ASSERT_EQ(0x00E1DC80u, MODULE_DATA_ADDR(AST_$DATA));
    ASSERT_EQ(0x00EC5400u, MODULE_DATA_ADDR(AST_$AOT));
    ASSERT_EQ(0x498, AST_$DATA_SIZE);               /* map: AST_ size = 498 */
    ASSERT_EQ(0xF960, AST_$AOT_SIZE);               /* map: AST_AOT size = F960 */
    /* AREA_ follows the AST_ segment in the map */
    ASSERT_EQ(0x00E1E118u, MODULE_DATA_ADDR(AST_$DATA) + AST_$DATA_SIZE);
    /* the two tables fill the segment exactly */
    ASSERT_EQ(AST_$AOT_SIZE,
              AST_MAX_ASTE * TARGET_ASTE_SIZE + AST_MAX_AOTE * TARGET_AOTE_SIZE);
    ASSERT_EQ(AST_MAX_ASTE, sizeof(AST_$AOT.aste) / sizeof(AST_$AOT.aste[0]));
    ASSERT_EQ(AST_MAX_AOTE, sizeof(AST_$AOT.aote) / sizeof(AST_$AOT.aote[0]));
}

TEST(map_symbols_in_the_tables)
{
    /* AST at the segment base, AOT after 504 target ASTEs */
    ASSERT_EQ(0, OFF(AST_$AOT, aste));
    ASSERT_EQ(0x00EC7B60u,
              MODULE_DATA_ADDR(AST_$AOT) + AST_MAX_ASTE * TARGET_ASTE_SIZE);
    /* ... and the AOT fills the rest up to 0xED4D60 */
    ASSERT_EQ(0x00ED4D60u, MODULE_DATA_ADDR(AST_$AOT) + AST_$AOT_SIZE);
    /* the element counts the image's sizes imply */
    ASSERT_EQ(504, AST_MAX_ASTE);
    ASSERT_EQ(280, AST_MAX_AOTE);
}

TEST(host_invariant_offsets)
{
    /* AOTH is the block base: (0x0,A5,D3w) */
    ASSERT_EQ(0, OFF(AST_$DATA, aoth[0]));
    ASSERT_EQ(0xFB, sizeof(AST_$DATA.aoth) / sizeof(AST_$DATA.aoth[0]));
    /* vol_indices element 1 is the first word after dism_ec, its bias
     * slot (element 0) the last word of dism_ec: (0x412,A5) + vol*2 */
    ASSERT_EQ(OFF(AST_$DATA, dism_ec) + (long long)sizeof(ec_$eventcount_t),
              OFF(AST_$DATA, vol_indices[1]));
    ASSERT_EQ(OFF(AST_$DATA, dism_ec) + (long long)sizeof(ec_$eventcount_t) - 2,
              OFF(AST_$DATA, vol_indices[0]));
    ASSERT_EQ(7, AST_VOL_INDEX_SLOTS);
    /* the scalar run AST_$FREE_ASTES..AST_$ASTE_L_CNT is 8 contiguous words */
    ASSERT_EQ(OFF(AST_$DATA, free_astes) + 2, OFF(AST_$DATA, free_aotes));
    ASSERT_EQ(OFF(AST_$DATA, free_astes) + 14, OFF(AST_$DATA, aste_l_cnt));
    ASSERT_EQ(0x0C, sizeof(AST_$DATA.not_found));
}

TEST(aste_bias)
{
    /* AST_$REMOVE_CORRUPTED_PAGE: 0xEC5400 + seg*0x14, then (-0x14,A2) */
    ASSERT_EQ((uintptr_t)&AST_$AOT.aste[0], (uintptr_t)AST_ASTE_ENTRY(1));
    ASSERT_EQ((uintptr_t)&AST_$AOT.aste[1], (uintptr_t)AST_ASTE_ENTRY(2));
    ASSERT_EQ((uintptr_t)&AST_$AOT.aste[AST_MAX_ASTE - 1],
              (uintptr_t)AST_ASTE_ENTRY(AST_MAX_ASTE));
}

TEST(image_contents_table_cells)
{
    /* +0x3F0 / +0x3F4 / +0x484 = 0xEC7B60 (AOT), +0x3FC / +0x400 = 0xEC5400 */
    ASSERT_EQ((uintptr_t)&AST_$AOT.aote[0], (uintptr_t)AST_$DATA.aote_scan_pos);
    ASSERT_EQ((uintptr_t)&AST_$AOT.aote[0], (uintptr_t)AST_$DATA.aote_limit);
    ASSERT_EQ((uintptr_t)&AST_$AOT.aote[0], (uintptr_t)AST_$DATA.update_scan);
    ASSERT_EQ((uintptr_t)&AST_$AOT.aste[0], (uintptr_t)AST_$DATA.aste_scan_pos);
    ASSERT_EQ((uintptr_t)&AST_$AOT.aste[0], (uintptr_t)AST_$DATA.aste_limit);
    ASSERT_EQ(0, (uintptr_t)AST_$DATA.free_aote_head);
    ASSERT_EQ(0, (uintptr_t)AST_$DATA.free_aste_head);
    ASSERT_EQ(0, (uintptr_t)AST_$DATA.dismount_failed_ptr);
}

TEST(image_contents_eventcounts)
{
    /* +0x408 / +0x428 / +0x44C: 00 00 00 00, then head = tail = self */
    ASSERT_EQ(0, AST_$DATA.dism_ec.value);
    ASSERT_EQ((uintptr_t)&AST_$DATA.dism_ec,
              (uintptr_t)AST_$DATA.dism_ec.waiter_list_head);
    ASSERT_EQ((uintptr_t)&AST_$DATA.dism_ec,
              (uintptr_t)AST_$DATA.dism_ec.waiter_list_tail);
    ASSERT_EQ(0, AST_$DATA.ast_in_trans_ec.value);
    ASSERT_EQ((uintptr_t)&AST_$DATA.ast_in_trans_ec,
              (uintptr_t)AST_$DATA.ast_in_trans_ec.waiter_list_head);
    ASSERT_EQ((uintptr_t)&AST_$DATA.ast_in_trans_ec,
              (uintptr_t)AST_$DATA.ast_in_trans_ec.waiter_list_tail);
    ASSERT_EQ(0, AST_$DATA.pmap_in_trans_ec.value);
    ASSERT_EQ((uintptr_t)&AST_$DATA.pmap_in_trans_ec,
              (uintptr_t)AST_$DATA.pmap_in_trans_ec.waiter_list_head);
    ASSERT_EQ((uintptr_t)&AST_$DATA.pmap_in_trans_ec,
              (uintptr_t)AST_$DATA.pmap_in_trans_ec.waiter_list_tail);
}

TEST(image_contents_scalars)
{
    int i;

    ASSERT_EQ(8, AST_$GROW_AHEAD_CNT);                  /* +0x46C: 00 08 */
    ASSERT_EQ(0xFFFF, AST_$UPDATE_TIMESTAMP);           /* +0x488: ff ff */
    ASSERT_EQ(0x0278301C, AST_$ATTR_TIMESTAMP_MASK);    /* +0x48C */
    /* everything else in the image is zero */
    for (i = 0; i < AST_AOTH_BUCKETS; i++) {
        ASSERT_EQ(0, (uintptr_t)AST_$DATA.aoth[i]);
    }
    for (i = 1; i < AST_VOL_INDEX_SLOTS; i++) {
        ASSERT_EQ(0, AST_$DATA.vol_indices[i]);
    }
    ASSERT_EQ(0, AST_$DISM_SEQN);
    ASSERT_EQ(0, AST_$DATA.vol_info_count);
    ASSERT_EQ(0, AST_$AOTE_SEQN);
    ASSERT_EQ(0, AST_$ALLOC_WORST_AOT);
    ASSERT_EQ(0, AST_$ALLOC_TOTAL_AOT);
    ASSERT_EQ(0, AST_$ALLOC_WORST_AST);
    ASSERT_EQ(0, AST_$ALLOC_TOTAL_AST);
    ASSERT_EQ(0, AST_$WS_FLT_CNT);
    ASSERT_EQ(0, AST_$PAGE_FLT_CNT);
    ASSERT_EQ(0, AST_$ALLOC_TOO_FEW_CNT);
    ASSERT_EQ(0, AST_$ALLOC_CNT);
    ASSERT_EQ(0, AST_$FREE_ASTES);
    ASSERT_EQ(0, AST_$FREE_AOTES);
    ASSERT_EQ(0, AST_$SIZE_AOT);
    ASSERT_EQ(0, AST_$SIZE_AST);
    ASSERT_EQ(0, AST_$ASTE_AREA_CNT);
    ASSERT_EQ(0, AST_$ASTE_R_CNT);
    ASSERT_EQ(0, AST_$ASTE_L_CNT);
    ASSERT_EQ(0, AST_$NOT_FOUND.uid.high);
    ASSERT_EQ(0, AST_$NOT_FOUND.uid.low);
    ASSERT_EQ(0, AST_$NOT_FOUND.flags);
    ASSERT_EQ(0, AST_$DATA.clobbered_uid.high);
    ASSERT_EQ(0, AST_$DATA.clobbered_uid.low);
}

TEST(tables_zero_filled)
{
    const uint8_t *p = (const uint8_t *)&AST_$AOT;
    size_t i;

    for (i = 0; i < sizeof(AST_$AOT); i++) {
        ASSERT_EQ(0, p[i]);
    }
}

TEST(code_reads_the_block)
{
    /* AST_$GET_DISM_SEQN: move.l (0x404,A5),D0 */
    AST_$DATA.dism_seqn = 0x12345678;
    ASSERT_EQ(0x12345678, AST_$GET_DISM_SEQN());
    AST_$DISM_SEQN = 0;
    ASSERT_EQ(0, AST_$GET_DISM_SEQN());
}

int main(void)
{
    printf("AST module data blocks (source-gmxj):\n");
    RUN_TEST(block_addresses_and_sizes);
    RUN_TEST(map_symbols_in_the_tables);
    RUN_TEST(host_invariant_offsets);
    RUN_TEST(aste_bias);
    RUN_TEST(image_contents_table_cells);
    RUN_TEST(image_contents_eventcounts);
    RUN_TEST(image_contents_scalars);
    RUN_TEST(tables_zero_filled);
    RUN_TEST(code_reads_the_block);
    printf("%d tests, %d failed\n", tests_run, tests_failed);
    return tests_failed ? 1 : 0;
}
